    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "The physical double-hub family: source.",
        H("Double-hub source"), Blocks(
            Paragraph(Text("Let m be a natural number at least one. The vertices are a centre, two hubs and m leaves at each hub. Each edge receives an integer total and a positive complementary split. The source endpoint receives k and the other endpoint receives n-k. The mass at a vertex is the sum of its assigned endpoints.")),
            Paragraph(Text("The weight is the product of binomial edge factors and factorial vertex factors over every vertex. At tau=-1 the spin sum equals the product of 1+(-1)^degree X^mass. Formal generators are indexed independently by r. Extracting Z_5 squared times Z_3 to the power 2m selects exactly two edges with total 3; every other edge has total 2. Every cutoff at least 3 gives the same extracted coefficient.")),
            Paragraph(Text("The all-vertex specialization is the expression labelled planarf2, equation (2.19), in Fiol, Martinez-Montoya and Rios Fukelman, arXiv:2006.06379v2. The printed product limit in (2.31) is a separate expression. No claim about an intended correction is needed.")),
            Paragraph(Text("Put H_r=1+X^r and S_r=sum of X^j for 0<=j<r. For odd d, use U=S_d,V=S_(d+1),W=S_(d+2),h=2d,N=d+1. For even d use U=H_d,V=H_(d+1),W=H_(d+2),h=2d-2,N=d+2. The independently defined polynomial is R_m=(1-X)^h Q_(m+1).")),
            Paragraph(Text("These new declarations are absent from the pinned statement-projection corpus. The supported omission records that projection gap; the mathematical argument and exact theorem statements are given in this document. No projection entry or judge is changed.")),
