                Blocks(Paragraph(Text("The generic extraction uses that new support classification, then evaluates the finite generating sum. Exact source statement: theorem coefficient_extract {E : Type} [Fintype E] [DecidableEq E]     {R : Type} [CommSemiring R] (m cutoff : \u2115)     (hE : Fintype.card E = 2*m+2) (a : (E \u2192 \u2115) \u2192 R) :     ((\u2211 n \u2208 Fintype.piFinset (fun _ : E => Finset.Icc 2 cutoff),       MvPolynomial.C (a n) * \u220f e : E, MvPolynomial.X (2*n e-1) :       MvPolynomial \u2115 R).coeff         (Finsupp.single 5 2 + Finsupp.single 3 (2*m))) =     \u2211 n \u2208 (Fintype.piFinset (fun _ : E => Finset.Icc 2 cutoff)).filter       (fun n => (\u2200 e : E, n e = 2 \u2228 n e = 3) \u2227         (Finset.univ.filter (fun e : E => n e = 3)).card = 2), a n."))), DescribeRole.Theorem),
